#!/bin/bash
# usage: run.sh <name> "<design brief>" [out suffix]
# Codex headless redesign of ONE Storm elite. Input = old hover cell on a flat #00FF40 key (silhouette/pose guide only). Output masters/<name>[_suffix].png on the same key.
D="$(cd "$(dirname "$0")" && pwd)"
N="$1"; BRIEF="$2"; SUF="$3"; OUT="masters/${N}${SUF}.png"
PROMPT="You are REDESIGNING ONE elite enemy ship for the STORM world (a gas-giant sky: dark violet-indigo clouds, white lightning). Attached image: ${N}_in.png = the current sprite on a flat green (#00FF40) key background, top-down view, nose up. Use it ONLY as the guide for silhouette class, role, pose, camera and footprint. Use your image generation tool to paint a NEW image of this ship redesigned from the ground up: re-think its parts (coils, rods, cannons, plating, vents, engines, glowing parts) and give every surface new detail, real materials and its own invented colour scheme, as described in the brief. Do not recolour the input and do not copy its grey palette. Hard-surface, grounded, believable machinery, NOT cartoony: crisp hard pixel-art edges with dense 4-6 tone ramps, rivets, panel lines, scratches, wear, bolts, cable runs, strong value contrast so it reads against a dark violet sky. Premium hand-finished 16-bit sprite quality, no flat fills, no hard colour banding, no region-by-region painting; colour changes happen at real part boundaries. It is an AIRBORNE machine (no wheels, legs or ground rig). The engine bells at the stern must be EMPTY, dark and unlit (flames are added later). Keep the glowing parts (energy) small, placed with intent. FORBIDDEN: pink, magenta, red, lime green, muddy grey-brown; NO outline of any kind (no pale rim, no white border, no glow halo around the ship): edges are just the painted body against the background. Background: perfectly flat #00FF40, no shadow, no gradient, no ground, no other objects; the ship centred with generous margin, nose up, same proportions and similar footprint as the input. DESIGN BRIEF: ${BRIEF} Output exactly one image. Save the final PNG to ${D}/${OUT} (copy it from the generated images folder if needed) and reply with just the path."
cd "$D"
printf "%s" "$PROMPT" | /private/tmp/claude-501/-Users-sina-Developer-Pause/4bec0c4f-4fa4-46dd-8c13-2a797152b684/scratchpad/codex_lock.sh ~/.local/bin/codex exec -s workspace-write -C "$D/in" -c model_reasoning_effort='"high"' -i "$D/in/${N}_in.png" --add-dir "$D/masters" -
